import{_ as a,Y as t,o as r,c as i,aq as s,H as l}from"./chunks/framework.CZHj4g6B.js";import"./chunks/theme.BZcG_oVy.js";const g=JSON.parse('{"title":"展望未来","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/about/future.md","filePath":"zh-cn/about/future.md"}'),n={name:"zh-cn/about/future.md"};function p(u,e,d,c,h,k){const o=t("NolebaseGitChangelog");return r(),i("div",null,[e[0]||(e[0]=s('<h1 id="looking-toward-the-future" tabindex="-1">展望未来 <a class="header-anchor" href="#looking-toward-the-future" aria-label="Permalink to &quot;展望未来&quot;">​</a></h1><blockquote><p>未来是美好的，也是不确定的，让我们共同期待 <code>YukiHookAPI</code> 在未来的发展空间。</p></blockquote><h2 id="unresolved-issues" tabindex="-1">未解决的问题 <a class="header-anchor" href="#unresolved-issues" aria-label="Permalink to &quot;未解决的问题&quot;">​</a></h2><blockquote><p>这里收录了 <code>YukiHookAPI</code> 尚未解决的问题。</p></blockquote><h3 id="yukihookprefsbridge" tabindex="-1">YukiHookPrefsBridge <a class="header-anchor" href="#yukihookprefsbridge" aria-label="Permalink to &quot;YukiHookPrefsBridge&quot;">​</a></h3><p>目前仅限完美支持 LSPosed，其它 Xposed 框架需要降级模块 API。</p><p>可能完全不支持太极，太极在高版本系统上需要更低的 API 才能适配。</p><p>部分 Xposed 模块开发者目前选择 Hook 目标 APP 内置 Sp 存储方案解决模块设置共享问题。</p><p>后期 Android 系统的权限将越来越严格，<code>selinux</code> 就是目前面临的一个大问题，有待讨论和研究。</p><div class="tip custom-block"><p class="custom-block-title">2023.10.06 更新</p><p>LSPosed 现已实验性推出了 <a href="https://github.com/libxposed" target="_blank" rel="noreferrer">Modern Xposed API</a>，它采用 Service 的方式与模块通信，这将能够解决模块数据存储的问题。</p><p>为了保证大部分模块的兼容性，后期 <strong>YukiHookAPI</strong> 计划使用自定义的 ContentProvider 实现模块与宿主的数据互通，敬请期待。</p></div><h2 id="future-plans" tabindex="-1">未来的计划 <a class="header-anchor" href="#future-plans" aria-label="Permalink to &quot;未来的计划&quot;">​</a></h2><blockquote><p>这里收录了 <code>YukiHookAPI</code> 可能会在后期添加的功能。</p></blockquote><h3 id="lite-version-supported-for-standalone-use" tabindex="-1">支持独立使用的 Lite 版本 <a class="header-anchor" href="#lite-version-supported-for-standalone-use" aria-label="Permalink to &quot;支持独立使用的 Lite 版本&quot;">​</a></h3><p>如果你喜欢 YukiHookAPI 的反射 API，但你的项目可能并不需要相关 Hook 功能。</p><p>那么这里有一个好消息要告诉你：</p><p><s>YukiHookAPI 的核心反射 API 已被解耦合为 <a href="https://github.com/HighCapable/YukiReflection" target="_blank" rel="noreferrer">YukiReflection</a> 项目，它现在能在任何 Android 项目中使用。</s></p><p>YukiReflection 项目由于很多未能解决的黑盒问题已被弃用，我们不再推荐任何人使用它，现在请迁移到全新设计的 <a href="https://github.com/HighCapable/KavaRef" target="_blank" rel="noreferrer">KavaRef</a>。</p><div class="tip custom-block"><p class="custom-block-title">待讨论</p><p>目前 API 只支持通过自动处理程序绑定到 <strong>xposed_init</strong>，若您不喜欢自动处理程序，一定要自己实现模块装载入口，未来会按照需求人数推出仅有 API 功能的 Lite 版本，你可向我们提出 <strong>issues</strong>。</p></div><p>API 已经提供了 Xposed 原生 API 监听接口，你可以 <a href="./../config/xposed-using.html#native-xposed-api-events">在这里</a> 找到或查看 Demo 的实现方法。</p><h3 id="milestone-plan" tabindex="-1">里程碑计划 <a class="header-anchor" href="#milestone-plan" aria-label="Permalink to &quot;里程碑计划&quot;">​</a></h3><p>下方这些计划已在 GitHub 的 <code>issues</code> 中发布，你可以查看每个项目的进度。</p><p>所有功能预计在 <code>2.0.0</code> 版本完成，敬请期待。</p><ul><li><a href="https://github.com/HighCapable/YukiHookAPI/issues/49" target="_blank" rel="noreferrer">New Xposed Module Config Plan</a></li><li><a href="https://github.com/HighCapable/YukiHookAPI/issues/48" target="_blank" rel="noreferrer">New Hook Entry Class</a></li><li><s><a href="https://github.com/HighCapable/YukiHookAPI/issues/33" target="_blank" rel="noreferrer">New Hook Code Style</a></s> (已由 <a href="https://github.com/HighCapable/KavaRef" target="_blank" rel="noreferrer">KavaRef</a> 取代)</li></ul>',23)),l(o)])}const P=a(n,[["render",p]]);export{g as __pageData,P as default};
